import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return 0.0
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    m = L.max()
    if m <= 0:
        return 0.0
    # ||f*f||_2^2 = sum_j (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3 over knots [0, *L, 0]
    Lp = np.concatenate(([0.0], L, [0.0]))
    l2sq = np.sum(Lp[:-1]**2 + Lp[:-1]*Lp[1:] + Lp[1:]**2) / 3.0
    # ||f*f||_1 = (sum h)^2
    l1 = s * s
    return l2sq / (l1 * m)


def _negR(h):
    return -_R(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = budget_seconds - 2.0
    if limit < 1.0:
        limit = budget_seconds * 0.8

    N = 201
    i = np.arange(N)
    h = np.exp(-((i - 100) / 25.0)**2)
    h = h / h.sum()

    if start is not None:
        start = np.asarray(start, dtype=float)
        if start.size > 0 and np.all(np.isfinite(start)) and start.sum() > 0:
            if _R(start) > _R(h):
                # resample start onto N points if needed
                if start.size == N:
                    h = start / start.sum()
                else:
                    xs = np.linspace(0, 1, start.size)
                    xn = np.linspace(0, 1, N)
                    h = np.interp(xn, xs, start)
                    if h.sum() > 0:
                        h = h / h.sum()

    best_h = h.copy()
    best_R = _R(h)

    bounds = [(0.0, None)] * N
    rng = np.random.default_rng(12345)

    cur = h.copy()
    while True:
        if time.process_time() - t0 > limit:
            break
        try:
            res = minimize(_negR, cur, method='L-BFGS-B', bounds=bounds,
                           jac='2-point', options={'maxiter': 500, 'maxfun': 20000})
            cand = np.clip(res.x, 0.0, None)
            if cand.sum() > 0:
                cand = cand / cand.sum()
                r = _R(cand)
                if r > best_R:
                    best_R = r
                    best_h = cand.copy()
                cur = cand
            else:
                cur = best_h.copy()
        except Exception:
            cur = best_h.copy()

        if time.process_time() - t0 > limit:
            break

        # perturb from best
        noise = 1.0 + 0.05 * rng.standard_normal(N)
        cur = np.clip(best_h * noise, 0.0, None)
        if cur.sum() > 0:
            cur = cur / cur.sum()
        else:
            cur = best_h.copy()

    return best_h

import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    # ||f*f||_2^2
    s2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if linf <= 0 or l1 <= 0:
        return 0.0
    return s2 / (l1 * linf)


def _make(p, s, N):
    t = np.linspace(-1.0, 1.0, N)
    return np.exp(-np.abs(t / s) ** p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + min(budget_seconds - 2.0, 28.0)

    best_h = None
    best_r = -1.0

    def consider(p, s, N):
        nonlocal best_h, best_r
        h = _make(p, s, N)
        r = _R(h)
        if r > best_r:
            best_r = r
            best_h = h
        return r

    # Coarse scan
    ps = np.linspace(1.0, 4.0, 61)
    ss = np.logspace(np.log10(0.03), np.log10(0.5), 40)
    N = 4001
    best_p, best_s = 2.0, 0.2
    for p in ps:
        if time.process_time() > deadline:
            break
        for s in ss:
            r = consider(p, s, N)
            if r == best_r:
                best_p, best_s = p, s

    # Refine around best
    def refine(pc, sc, dp, ds, N, steps):
        nonlocal best_p, best_s
        for _ in range(steps):
            if time.process_time() > deadline:
                return
            ps_ = np.linspace(max(0.5, pc - dp), pc + dp, 21)
            ss_ = np.linspace(max(0.01, sc - ds), sc + ds, 21)
            for p in ps_:
                if time.process_time() > deadline:
                    return
                for s in ss_:
                    r = consider(p, s, N)
                    if r == best_r:
                        best_p, best_s = p, s
            pc, sc = best_p, best_s
            dp *= 0.4
            ds *= 0.4

    refine(best_p, best_s, 0.3, 0.05, 4001, 4)

    # Increase N and refine again
    if time.process_time() < deadline:
        consider(best_p, best_s, 8001)
        refine(best_p, best_s, 0.05, 0.01, 8001, 4)

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # Keep the base if it is better
    if start is not None:
        rs = _R(np.asarray(start, dtype=float))
        if rs > best_r:
            return np.asarray(start, dtype=float)

    return best_h

