import numpy as np
import time
from scipy.optimize import minimize


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def _resample(h, N):
    x_old = (np.arange(h.size) + 0.5) / h.size
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)
    rng = np.random.default_rng(20240607)

    def try_candidate(cand):
        nonlocal best, bestR
        cand = np.clip(np.asarray(cand, dtype=float), 0.0, None)
        if cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()
            return True
        return False

    def refine(h_init, maxiter=400):
        # Gradient-based polish in log-space, keeps best if improved.
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 8.0)] * N,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 12})
            try_candidate(np.exp(res.x))
        except Exception:
            return

    # Step 1: refine current best at its own N and a few nearby sizes.
    base_N = best.size
    for N in [base_N, 50, 75, 100, 150, 200, 300]:
        if not time_left():
            break
        refine(_resample(best, N), maxiter=500)

    # Step 2: alternate between gradient polish and stochastic block search.
    step = 0.12
    it = 0
    while time_left():
        it += 1
        # Gradient polish on current best (cheap, high yield)
        if it % 4 == 1 and time_left():
            refine(best.copy(), maxiter=300)
            if not time_left():
                break

        # Stochastic block perturbation on current best
        cand = best.copy()
        n = cand.size
        mode = rng.random()
        if mode < 0.55:
            k = int(rng.integers(1, max(2, n // 3)))
            i0 = int(rng.integers(0, n - k + 1))
            cand[i0:i0 + k] *= np.exp(rng.normal(0, step, k))
        elif mode < 0.8:
            k = int(rng.integers(1, max(2, n // 4)))
            i0 = int(rng.integers(0, n - k + 1))
            bump = rng.normal(0, step) * np.hanning(k)
            cand[i0:i0 + k] += bump * cand[i0:i0 + k].mean()
        else:
            kern = np.array([1.0, 2.0, 1.0])
            cand = np.convolve(cand, kern, mode='same')

        if try_candidate(cand) and time_left():
            # Successful move: polish it immediately.
            refine(best.copy(), maxiter=200)

        # Occasionally resample to nearby N to change resolution.
        if it % 40 == 0 and time_left():
            N = int(max(20, min(20000, best.size * rng.choice([0.7, 1.4, 2.0, 0.5]))))
            if try_candidate(_resample(best, N)) and time_left():
                refine(best.copy(), maxiter=300)

        if it % 30 == 0:
            step = max(0.004, step * 0.93)

    return best

