def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    rng = np.random.default_rng(12345)

    def upsample(h, N):
        x_old = (np.arange(h.size) + 0.5) / h.size
        x_new = (np.arange(N) + 0.5) / N
        return np.interp(x_new, x_old, h)

    def refine(h_init):
        nonlocal best, bestR
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return False
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': 2000, 'maxfun': 20000})
            cand = np.exp(res.x)
        except Exception:
            return False
        cand = np.clip(cand, 0.0, None)
        if cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()
            return True
        return False

    def split_top(h, k):
        # split k steps with largest |h[i+1]-h[i]| into two equal-height sub-steps
        h = np.asarray(h, dtype=float)
        n = h.size
        if n < 2 or k <= 0:
            return h.copy()
        diffs = np.abs(np.diff(h))
        k = min(k, n - 1)
        idx = np.argsort(diffs)[::-1][:k]
        idx = np.sort(idx)
        out = []
        split_set = set(idx.tolist())
        for i in range(n):
            out.append(h[i])
            if i in split_set:
                out.append(h[i])
        return np.array(out)

    def merge_smallest(h, k):
        # merge adjacent pairs with smallest height difference
        h = np.asarray(h, dtype=float)
        n = h.size
        if n < 3 or k <= 0:
            return h.copy()
        diffs = np.abs(np.diff(h))
        k = min(k, n // 2)
        idx = np.argsort(diffs)[:k]
        merge_set = set(idx.tolist())
        out = []
        i = 0
        while i < n:
            if i in merge_set and i + 1 < n:
                out.append(0.5 * (h[i] + h[i + 1]))
                i += 2
            else:
                out.append(h[i])
                i += 1
        return np.array(out)

    # First: try to refine the start itself at its own N.
    if time_left():
        refine(best.copy())

    # Adaptive splitting / merging loop around current best.
    ks = [5, 10, 20, 40]
    round_idx = 0
    while time_left():
        base = best.copy()
        improved = False
        # Splitting candidates
        for k in ks:
            if not time_left():
                break
            cand = split_top(base, k)
            if cand.size > 200000:
                continue
            if refine(cand):
                improved = True
        # Merging candidates
        for k in [5, 10, 20]:
            if not time_left():
                break
            cand = merge_smallest(base, k)
            if cand.size < 2:
                continue
            if refine(cand):
                improved = True
