        if not improved:
            # Perturb current best in log space at its own N and refine
            if not time_left():
                break
            N = best.size
            sigma = [0.03, 0.06, 0.12][round_idx % 3]
            x = np.log(best + 1e-12) + rng.normal(0.0, sigma, N)
            refine(np.exp(x))
            # Also try a small upsample to escape
            if time_left() and best.size < 200000:
                cand = upsample(best, min(best.size * 2, 200000))
                refine(cand)

    return best

