    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.clip(h, 0.0, None)
        if h.sum() <= 0:
            h = np.ones(50)
    else:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h.copy()
    bestR = R_of(best)
    rng = np.random.default_rng(98765)

    def try_candidate(cand):
        nonlocal best, bestR
        cand = np.clip(cand, 0.0, None)
        if cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()
            return True
        return False

    # Try a spread of N values by resampling start.
    for N in [45, 55, 70, 90, 120, 160, 220, 300, 450, 700, 1000, 1500]:
        if not time_left():
            break
        try_candidate(_resample(best, N))

    def coord_sweep(step):
        nonlocal best, bestR
        improved = False
        n = best.size
        order = rng.permutation(n)
        for i in order:
            if not time_left():
                return improved
            cur = best[i]
            if cur <= 0:
                continue
            for f in (1.0 + step, 1.0 - step, 1.0 + 0.6 * step, 1.0 - 0.6 * step,
                      1.0 + 0.3 * step, 1.0 - 0.3 * step):
                cand = best.copy()
                cand[i] = cur * f
                r = R_of(cand)
                if r > bestR:
                    bestR = r
                    best = cand
                    improved = True
                    break
        return improved

