from scipy.optimize import minimize


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def smooth_R_grad(x, beta):
    """F = -q/(s^2 * m_beta), m_beta = logsumexp(beta*Lf)/beta, h=exp(x)."""
    h = np.exp(x)
    N = h.size
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10, np.zeros(N)

    Lc = np.convolve(h, h)
    Lf = np.concatenate(([0.0], Lc, [0.0]))

    bL = beta * Lf
    mx = bL.max()
    e = np.exp(bL - mx)
    Z = e.sum()
    m_beta = (mx + np.log(Z)) / beta
    if m_beta <= 0 or not np.isfinite(m_beta):
        return 1e10, np.zeros(N)

    q = (Lf[:-1] * Lf[:-1] + Lf[:-1] * Lf[1:] + Lf[1:] * Lf[1:]).sum() / 3.0
    F = -q / (s * s * m_beta)

    M = Lf.size
    dq = np.zeros(M)
    dq[:-1] += (2.0 * Lf[:-1] + Lf[1:]) / 3.0
    dq[1:] += (Lf[:-1] + 2.0 * Lf[1:]) / 3.0

    soft = e / Z
    denom = s * s * m_beta
    dF_dLf = -dq / denom + q * soft / (s * s * m_beta * m_beta)
    dF_ds = 2.0 * q / (s * s * s * m_beta)

    dF_dLc = dF_dLf[1:2 * N]
    dF_dh = np.correlate(dF_dLc, h, mode='valid')
    dF_dh += dF_ds
    grad = dF_dh * h
    if not np.all(np.isfinite(grad)):
        grad = np.nan_to_num(grad, nan=0.0, posinf=0.0, neginf=0.0)
    return F, grad


def _pnorm_grad(x, p):
    """F = -q/(s^2 * m_p), m_p = ||Lf||_p. Analytic gradient."""
    h = np.exp(x)
    N = h.size
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10, np.zeros(N)
    Lc = np.convolve(h, h)
    Lf = np.concatenate(([0.0], Lc, [0.0]))
    Lp = np.power(np.maximum(Lf, 0.0), p)
    sp = Lp.sum()
    if not np.isfinite(sp) or sp <= 0:
        return 1e10, np.zeros(N)
    m_p = sp ** (1.0 / p)
    if m_p <= 0 or not np.isfinite(m_p):
        return 1e10, np.zeros(N)
    q = (Lf[:-1] * Lf[:-1] + Lf[:-1] * Lf[1:] + Lf[1:] * Lf[1:]).sum() / 3.0
    F = -q / (s * s * m_p)

    M = Lf.size
    dq = np.zeros(M)
    dq[:-1] += (2.0 * Lf[:-1] + Lf[1:]) / 3.0
    dq[1:] += (Lf[:-1] + 2.0 * Lf[1:]) / 3.0

    # dm_p/dLf_j = (Lf_j^{p-1}) / m_p^{p-1}
    dm = np.power(np.maximum(Lf, 1e-300), p - 1.0) / (m_p ** (p - 1.0))
    denom = s * s * m_p
    dF_dLf = -dq / denom + q * dm / (s * s * m_p * m_p)
    dF_ds = 2.0 * q / (s * s * s * m_p)

    dF_dLc = dF_dLf[1:2 * N]
    dF_dh = np.correlate(dF_dLc, h, mode='valid')
    dF_dh += dF_ds
    grad = dF_dh * h
    if not np.all(np.isfinite(grad)):
        grad = np.nan_to_num(grad, nan=0.0, posinf=0.0, neginf=0.0)
    return F, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 50
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    def upsample(h, N):
        x_old = (np.arange(h.size) + 0.5) / h.size
        x_new = (np.arange(N) + 0.5) / N
        return np.interp(x_new, x_old, h)

    def try_candidate(cand):
        nonlocal best, bestR
        cand = np.clip(np.asarray(cand, dtype=float), 0.0, None)
        if cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    def homotopy_analytic(h_init, betas):
        h_cur = np.clip(h_init, 0.0, None)
        if h_cur.sum() <= 0:
            return
        N = h_cur.size
        x = np.log(h_cur + 1e-12)
        for beta in betas:
            if not time_left():
                break
            try:
                res = minimize(smooth_R_grad, x, args=(beta,), method='L-BFGS-B',
                               jac=True, bounds=[(-20.0, 10.0)] * N,
                               options={'maxiter': 3000, 'maxfun': 30000,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                x = res.x
            except Exception:
                break
            try_candidate(np.exp(x))

    def homotopy_pnorm(h_init, ps):
        h_cur = np.clip(h_init, 0.0, None)
        if h_cur.sum() <= 0:
            return
        N = h_cur.size
        x = np.log(h_cur + 1e-12)
        for p in ps:
            if not time_left():
                break
            try:
                res = minimize(_pnorm_grad, x, args=(p,), method='L-BFGS-B',
                               jac=True, bounds=[(-20.0, 10.0)] * N,
                               options={'maxiter': 3000, 'maxfun': 30000,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                x = res.x
            except Exception:
                break
            try_candidate(np.exp(x))

    def refine(h_init):
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': 2000, 'maxfun': 20000})
            try_candidate(np.exp(res.x))
        except Exception:
            return

    # Phase 1: analytic-gradient logsumexp homotopy on start's N.
    if time_left():
        homotopy_analytic(best, [2000, 5000, 10000, 20000, 50000, 100000, 200000])

    # Phase 2: p-norm homotopy (better at high p) at current N.
    if time_left():
        homotopy_pnorm(best, [8, 16, 32, 64, 128, 256, 512])

    # Phase 3: upsample and continue at growing N.
    for N in (100, 200, 400):
        if not time_left():
            break
        homotopy_analytic(upsample(best, N), [20000, 50000, 100000, 200000])
        if not time_left():
            break
        homotopy_pnorm(best, [64, 128, 256, 512])

    # Phase 4: exact-R polish at multiple N.
    for N in (50, 100, 200, 400):
        if not time_left():
            break
        refine(upsample(best, N))

    # Phase 5: final high-resolution p-norm push with remaining budget.
    for N in (200, 400):
        if not time_left():
            break
        homotopy_pnorm(upsample(best, N), [128, 256, 512, 1024])
        if not time_left():
            break
        homotopy_analytic(upsample(best, N), [100000, 200000, 400000])

    if not time_left():
        refine(best)

    return best

