    def param_h(alpha, beta, N):
        i = np.arange(N) + 0.5
        t = i / N
        # guard against t=1 and zero
        base = np.power(i, -alpha)
        tail = np.power(np.clip(1.0 - t, 1e-12, None), -beta)
        h = base * tail
        if not np.all(np.isfinite(h)):
            return None
        return h

