    best_alpha, best_beta = 0.5, 0.0
    best_param_R = -1.0
    if time_left():
        alphas = np.linspace(0.3, 0.7, 41)
        betas = np.linspace(-0.3, 0.3, 25)
        for a in alphas:
            for b in betas:
                if not time_left():
                    break
                h = param_h(a, b, N_scan)
                if h is None:
                    continue
                r = R_of(h)
                if r > best_param_R:
                    best_param_R = r
                    best_alpha, best_beta = a, b
            if not time_left():
