import time
from scipy.optimize import minimize


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def smooth_R_grad(x, beta):
    h = np.exp(x)
    N = h.size
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10, np.zeros(N)

    Lc = np.convolve(h, h)
    Lf = np.concatenate(([0.0], Lc, [0.0]))

    bL = beta * Lf
    mx = bL.max()
    e = np.exp(bL - mx)
    Z = e.sum()
    m_beta = (mx + np.log(Z)) / beta
    if m_beta <= 0 or not np.isfinite(m_beta):
        return 1e10, np.zeros(N)

    q = (Lf[:-1] * Lf[:-1] + Lf[:-1] * Lf[1:] + Lf[1:] * Lf[1:]).sum() / 3.0

    F = -q / (s * s * m_beta)

    M = Lf.size
    dq = np.zeros(M)
    dq[:-1] += (2.0 * Lf[:-1] + Lf[1:]) / 3.0
    dq[1:] += (Lf[:-1] + 2.0 * Lf[1:]) / 3.0

    soft = e / Z

    denom = s * s * m_beta
    dF_dLf = -dq / denom + q * soft / (s * s * m_beta * m_beta)

    dF_ds = 2.0 * q / (s * s * s * m_beta)

    dF_dLc = dF_dLf[1:2 * N]
    dF_dh = np.correlate(dF_dLc, h, mode='valid')
    dF_dh += dF_ds

    grad = dF_dh * h
    if not np.all(np.isfinite(grad)):
        grad = np.nan_to_num(grad, nan=0.0, posinf=0.0, neginf=0.0)
    return F, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 50
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    def upsample(h, N):
        x_old = (np.arange(h.size) + 0.5) / h.size
        x_new = (np.arange(N) + 0.5) / N
        return np.interp(x_new, x_old, h)

    # --- Parametric scan: h_i = (i+0.5)^(-alpha) * (1-(i+0.5)/N)^(-beta) ---
    def param_h(alpha, beta, N):
        i = np.arange(N) + 0.5
        t = i / N
        base = np.power(i, -alpha)
        tail = np.power(np.clip(1.0 - t, 1e-12, None), -beta)
        h = base * tail
        if not np.all(np.isfinite(h)):
            return None
        return h

    N_scan = 2000
    best_alpha, best_beta = 0.5, 0.0
    best_param_R = -1.0
    if time_left():
        alphas = np.linspace(0.3, 0.7, 41)
        betas = np.linspace(-0.3, 0.3, 25)
        for a in alphas:
            for b in betas:
                if not time_left():
                    break
                h = param_h(a, b, N_scan)
                if h is None:
                    continue
                r = R_of(h)
                if r > best_param_R:
                    best_param_R = r
                    best_alpha, best_beta = a, b
            if not time_left():
                break

    if time_left():
        def negR_param(p):
            a, b = p
            h = param_h(a, b, N_scan)
            if h is None:
                return 1.0
            return -R_of(h)

        try:
            res = minimize(negR_param, [best_alpha, best_beta],
                           method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-8,
                                    'maxiter': 400, 'maxfev': 800})
            a, b = res.x
            h = param_h(a, b, N_scan)
            if h is not None:
                r = R_of(h)
                if r > best_param_R:
                    best_param_R = r
                    best_alpha, best_beta = a, b
        except Exception:
            pass

    if best_param_R > bestR:
        h_param = param_h(best_alpha, best_beta, N_scan)
        if h_param is not None:
            best = h_param.copy()
            bestR = best_param_R

