    def two_sing_h(c, s_frac, N):
        i = np.arange(N) + 0.5
        h = np.power(i, -0.5)
        s = s_frac * N
        # second singularity at index s: term ((i - s) + 0.5)^-0.5 for i > s
        mask = i > s
        if np.any(mask):
            arg = (i[mask] - s) + 0.5
            arg = np.clip(arg, 1e-9, None)
            h[mask] += c * np.power(arg, -0.5)
        if not np.all(np.isfinite(h)):
            return None
        return h

    if time_left():
        best_c, best_sf = 0.0, 0.0
        best_two_R = -1.0
        for c in (0.25, 0.5, 1.0, 2.0):
            for sf in (0.25, 0.5, 0.75):
                if not time_left():
                    break
                h = two_sing_h(c, sf, N_scan)
                if h is None:
                    continue
                r = R_of(h)
                if r > best_two_R:
                    best_two_R = r
                    best_c, best_sf = c, sf
            if not time_left():
                break
        if best_two_R > bestR:
            h_two = two_sing_h(best_c, best_sf, N_scan)
            if h_two is not None:
                best = h_two.copy()
                bestR = best_two_R

    def homotopy_analytic(h_init, betas):
        nonlocal best, bestR
        h_cur = np.clip(h_init, 0.0, None)
        if h_cur.sum() <= 0:
            return
        N = h_cur.size
        x = np.log(h_cur + 1e-12)
        for beta in betas:
            if not time_left():
                break
            try:
                res = minimize(smooth_R_grad, x, args=(beta,), method='L-BFGS-B',
                               jac=True,
                               bounds=[(-20.0, 10.0)] * N,
                               options={'maxiter': 3000, 'maxfun': 30000,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                x = res.x
            except Exception:
                break
            cand = np.exp(x)
            cand = np.clip(cand, 0.0, None)
            if cand.sum() <= 0:
                continue
            r = R_of(cand)
            if r > bestR:
                bestR = r
                best = cand.copy()

    # Exact polish: L-BFGS-B on -R with log parametrization
    def exact_polish(h_init, maxiter=2000, maxfun=20000):
        nonlocal best, bestR
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': maxiter, 'maxfun': maxfun})
            cand = np.exp(res.x)
        except Exception:
            return
        cand = np.clip(cand, 0.0, None)
        if cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    # Main homotopy at N=50 from best
    if time_left():
        homotopy_analytic(best, [1000, 2000, 5000, 10000, 20000, 50000, 100000])

    for N in (100, 200):
        if not time_left():
            break
        homotopy_analytic(upsample(best, N), [5000, 20000, 50000, 100000])

    # EXPERIMENT: exact_polish at N=2000 and N=4000
    for N in (2000, 4000):
        if not time_left():
            break
        exact_polish(upsample(best, N))

    # Keep base's final small-N refinements if budget remains
    Ns = [50, 100, 200]
    for N in Ns:
        if not time_left():
            break
        exact_polish(upsample(best, N))

    return best

