    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def R_of_fft(h):
    """Exact R using FFT convolution (faster for large N)."""
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    N = h.size
    nfft = 1
    while nfft < 2 * N:
        nfft *= 2
    H = np.fft.rfft(h, nfft)
    c = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    L = np.empty(2 * N + 1)
    L[0] = 0.0
    L[1:2 * N] = c
    L[2 * N] = 0.0
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def smooth_R_grad(x, beta):
    h = np.exp(x)
    N = h.size
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10, np.zeros(N)

    Lc = np.convolve(h, h)
    Lf = np.concatenate(([0.0], Lc, [0.0]))

    bL = beta * Lf
    mx = bL.max()
    e = np.exp(bL - mx)
    Z = e.sum()
    m_beta = (mx + np.log(Z)) / beta
    if m_beta <= 0 or not np.isfinite(m_beta):
        return 1e10, np.zeros(N)

    q = (Lf[:-1] * Lf[:-1] + Lf[:-1] * Lf[1:] + Lf[1:] * Lf[1:]).sum() / 3.0

    F = -q / (s * s * m_beta)

    M = Lf.size
    dq = np.zeros(M)
    dq[:-1] += (2.0 * Lf[:-1] + Lf[1:]) / 3.0
    dq[1:] += (Lf[:-1] + 2.0 * Lf[1:]) / 3.0

    soft = e / Z

    denom = s * s * m_beta
    dF_dLf = -dq / denom + q * soft / (s * s * m_beta * m_beta)

    dF_ds = 2.0 * q / (s * s * s * m_beta)

    dF_dLc = dF_dLf[1:2 * N]
    dF_dh = np.correlate(dF_dLc, h, mode='valid')
    dF_dh += dF_ds

    grad = dF_dh * h
    if not np.all(np.isfinite(grad)):
        grad = np.nan_to_num(grad, nan=0.0, posinf=0.0, neginf=0.0)
    return F, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 50
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    def upsample(h, N):
        x_old = (np.arange(h.size) + 0.5) / h.size
        x_new = (np.arange(N) + 0.5) / N
        return np.interp(x_new, x_old, h)

    # --- Parametric scan with gamma offset: h_i = ((i+gamma)/N)^(-alpha) * (1-(i+gamma)/N)^(-beta) ---
    def param_h(alpha, beta, gamma, N):
        i = np.arange(N) + gamma
        t = i / N
        base = np.power(i, -alpha)
        tail = np.power(np.clip(1.0 - t, 1e-12, None), -beta)
        h = base * tail
        if not np.all(np.isfinite(h)):
            return None
        return h

    N_scan = 2000
    best_alpha, best_beta, best_gamma = 0.5, 0.0, 0.5
    best_param_R = -1.0
    if time_left():
        gammas = np.linspace(0.22, 0.55, 17)
        alphas = np.linspace(0.3, 0.7, 21)
        betas = np.linspace(-0.5, 0.5, 21)
        for g in gammas:
            for a in alphas:
                for b in betas:
                    if not time_left():
                        break
                    h = param_h(a, b, g, N_scan)
                    if h is None:
                        continue
                    r = R_of_fft(h)
                    if r > best_param_R:
                        best_param_R = r
                        best_alpha, best_beta, best_gamma = a, b, g
                if not time_left():
                    break
            if not time_left():
                break

    # Refine (alpha, beta, gamma) with Nelder-Mead on exact R
    if time_left():
        def negR_param(p):
            a, b, g = p
            h = param_h(a, b, g, N_scan)
            if h is None:
                return 1.0
            return -R_of_fft(h)

        try:
            res = minimize(negR_param, [best_alpha, best_beta, best_gamma],
                           method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-9,
                                    'maxiter': 600, 'maxfev': 1200})
            a, b, g = res.x
            h = param_h(a, b, g, N_scan)
            if h is not None:
                r = R_of_fft(h)
                if r > best_param_R:
                    best_param_R = r
                    best_alpha, best_beta, best_gamma = a, b, g
        except Exception:
            pass

    # Use the best parametric shape as a starting point if it beats start.
    if best_param_R > bestR:
        h_param = param_h(best_alpha, best_beta, best_gamma, N_scan)
        if h_param is not None:
            best = h_param.copy()
            bestR = best_param_R

    def homotopy_analytic(h_init, betas):
        nonlocal best, bestR
        h_cur = np.clip(h_init, 0.0, None)
        if h_cur.sum() <= 0:
            return
        N = h_cur.size
        x = np.log(h_cur + 1e-12)
        for beta in betas:
            if not time_left():
                break
            try:
                res = minimize(smooth_R_grad, x, args=(beta,), method='L-BFGS-B',
                               jac=True,
                               bounds=[(-20.0, 10.0)] * N,
                               options={'maxiter': 3000, 'maxfun': 30000,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                x = res.x
            except Exception:
                break
            cand = np.exp(x)
            cand = np.clip(cand, 0.0, None)
            if cand.sum() <= 0:
                continue
            r = R_of(cand)
            if r > bestR:
                bestR = r
                best = cand.copy()

    # Main homotopy at N=50 from best (start or parametric).
    if time_left():
        homotopy_analytic(best, [1000, 2000, 5000, 10000, 20000, 50000, 100000])

    for N in (100, 200):
        if not time_left():
            break
        homotopy_analytic(upsample(best, N), [5000, 20000, 50000, 100000])

    def refine(h_init):
        nonlocal best, bestR
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': 2000, 'maxfun': 20000})
            cand = np.exp(res.x)
        except Exception:
            return
        cand = np.clip(cand, 0.0, None)
        if cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    Ns = [50, 100, 200]
    for N in Ns:
        if not time_left():
            break
        refine(upsample(best, N))

    # --- New: exact_polish at N=2000 and N=4000 ---
    def exact_polish(h_init, maxiter=1500):
        nonlocal best, bestR
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of_fft(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10})
            cand = np.exp(res.x)
        except Exception:
            return
        cand = np.clip(cand, 0.0, None)
        if cand.sum() <= 0:
            return
        r = R_of_fft(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    for N in (2000, 4000):
        if not time_left():
            break
        exact_polish(upsample(best, N))

    # If time remains, try a bit more homotopy at high N
    if time_left():
        homotopy_analytic(upsample(best, 2000),
                          [200000, 500000, 1000000])

    return best

