def recurrence_candidate(M, N):
    """Build h with h_0=1 and sum_{i=0}^{n} h_i h_{n-i} = M for n=1..N-1.
    Returns array of length N (possibly truncated) or None."""
    h = np.zeros(N)
    h[0] = 1.0
    for n in range(1, N):
        if n == 1:
            s = 0.0
        else:
            s = np.dot(h[1:n], h[n - 1:0:-1])
        val = (M - s) / (2.0 * h[0])
        if not np.isfinite(val) or val <= 0.0:
            return h[:n] if n > 1 else None
        h[n] = val
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 50
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    def upsample(h, N):
        x_old = (np.arange(h.size) + 0.5) / h.size
        x_new = (np.arange(N) + 0.5) / N
        return np.interp(x_new, x_old, h)

    # --- Deterministic recurrence candidate at N=4000 ---
    N_rec = 4000
    if time_left():
        Ms = np.exp(np.linspace(np.log(0.02), np.log(5.0), 200))
        best_M = None
        best_rec_R = -1.0
        best_rec_h = None
        for M in Ms:
            if not time_left():
                break
            h = recurrence_candidate(M, N_rec)
            if h is None or h.size < 10:
                continue
            r = R_of_fft(h)
            if r > best_rec_R:
                best_rec_R = r
                best_M = M
                best_rec_h = h.copy()

        # Refine M with Nelder-Mead on exact R
        if best_M is not None and time_left():
            def negR_M(p):
                M = float(p[0])
                if M <= 0:
                    return 1.0
                h = recurrence_candidate(M, N_rec)
                if h is None or h.size < 10:
                    return 1.0
                return -R_of_fft(h)

            try:
                res = minimize(negR_M, [best_M], method='Nelder-Mead',
                               options={'xatol': 1e-5, 'fatol': 1e-10,
                                        'maxiter': 200, 'maxfev': 400})
                M2 = float(res.x[0])
                if M2 > 0:
                    h2 = recurrence_candidate(M2, N_rec)
                    if h2 is not None and h2.size >= 10:
                        r2 = R_of_fft(h2)
                        if r2 > best_rec_R:
                            best_rec_R = r2
                            best_M = M2
                            best_rec_h = h2.copy()
            except Exception:
                pass

        if best_rec_h is not None and best_rec_R > bestR:
            best = best_rec_h.copy()
            bestR = best_rec_R

