        if time_left():
            def gap(M):
                if M <= 0:
                    return np.inf
                h = recurrence_candidate(M, N_rec)
                if h is None or h.size < N_rec:
                    return np.nan
                c = np.convolve(h, h)
                # c_N = sum_{i=1}^{N-1} h_i h_{N-i} (h_N=0)
                cN = float(np.dot(h[1:N_rec], h[N_rec - 1:0:-1]))
                return cN - M

            gaps = []
            Ms_valid = []
            for M in Ms:
                if not time_left():
                    break
                g = gap(M)
                if np.isfinite(g):
                    gaps.append(g)
                    Ms_valid.append(M)

            M_star = None
            if len(gaps) >= 2:
                gaps = np.asarray(gaps)
                Ms_valid = np.asarray(Ms_valid)
                # find bracket with sign change
                bracket = None
                for i in range(len(gaps) - 1):
                    if gaps[i] == 0.0:
                        bracket = (Ms_valid[i], Ms_valid[i])
                        break
                    if gaps[i] * gaps[i + 1] < 0:
                        bracket = (Ms_valid[i], Ms_valid[i + 1])
                        break
                if bracket is not None:
                    if bracket[0] == bracket[1]:
                        M_star = bracket[0]
                    else:
