                        best = h_star.copy()

    # --- exact_polish ---
    def exact_polish(h_init, maxiter=1500):
        nonlocal best, bestR
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of_fft(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10})
            cand = np.exp(res.x)
        except Exception:
            return
        cand = np.clip(cand, 0.0, None)
        if cand.sum() <= 0:
            return
        r = R_of_fft(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    for N in (4000, 8000):
        if not time_left():
            break
        exact_polish(upsample(best, N))

    while time_left():
        N = 8000
        exact_polish(upsample(best, N), maxiter=800)
        if not time_left():
            break
        exact_polish(upsample(best, 12000), maxiter=400)

    return best

