    c = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    L = np.empty(2 * N + 1)
    L[0] = 0.0
    L[1:2 * N] = c
    L[2 * N] = 0.0
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def recurrence_candidate(M, N):
    """Build h with h_0=1 and sum_{i=0}^{n} h_i h_{n-i} = M for n=1..N-1.
    Returns array of length N (possibly truncated) or None."""
    h = np.zeros(N)
    h[0] = 1.0
    for n in range(1, N):
        if n == 1:
            s = 0.0
        else:
            s = np.dot(h[1:n], h[n - 1:0:-1])
        val = (M - s) / (2.0 * h[0])
        if not np.isfinite(val) or val <= 0.0:
            return h[:n] if n > 1 else None
        h[n] = val
    return h


def tapered_recurrence(N, lam, q):
    """h_0=1; h_n = (target_n - sum_{i=1}^{n-1} h_i h_{n-i}) / 2, target_n = 1 - lam*(n/(N-1))^q.
    Discard if any nonpositive/nonfinite height."""
    h = np.zeros(N)
    h[0] = 1.0
    denom_n = float(N - 1) if N > 1 else 1.0
    for n in range(1, N):
        t = n / denom_n
        target = 1.0 - lam * (t ** q)
        if n == 1:
            s = 0.0
        else:
            s = np.dot(h[1:n], h[n - 1:0:-1])
        val = (target - s) / (2.0 * h[0])
        if not np.isfinite(val) or val <= 0.0:
            return None
        h[n] = val
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
