        x_new = (np.arange(N) + 0.5) / N
        return np.interp(x_new, x_old, h)

    # --- Experiment: tapered-flat recurrence scan at N=4000 ---
    N_rec = 4000
    if time_left():
        lams = [-0.05, -0.02, 0.0, 0.02, 0.05, 0.1]
        qs = [1, 2, 4]
        best_rec_R = -1.0
        best_rec_h = None
        for lam in lams:
            for q in qs:
                if not time_left():
