    # --- exact_polish (exact-gradient polish) ---
    def exact_polish(h_init, maxiter=1500):
        nonlocal best, bestR
        h_init = np.clip(h_init, 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
