    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def upsample(h, N):
    x_old = (np.arange(h.size) + 0.5) / h.size
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def downsample(h, N):
    return upsample(h, N)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of_fft(best)

    # --- Multi-scale multiplicative bump polish using Nelder-Mead on a small basis.
    # Perturbation: h_i *= exp(sum_k c_k * basis_k(t_i)).
    # Basis: localized smooth bumps at a range of scales + global polynomial terms.
    def make_basis(N, nbump, scales):
        t = (np.arange(N) + 0.5) / N
        cols = []
        # global polynomial terms
        for k in (1, 2, 3):
            cols.append(t ** k)
        # localized cosine bumps across support
        for p in nbump:
            for sc in scales:
                cols.append(np.exp(-((t - p) / sc) ** 2))
        return np.array(cols)  # (K, N)

    def polish_basis(h_init, nbump=8, scales=(0.05, 0.1, 0.2, 0.4),
                     maxiter=400, n_try=3):
        nonlocal best, bestR
        N = h_init.size
        B = make_basis(N, np.linspace(0.1, 0.9, nbump), scales)
        K = B.shape[0]
        logh0 = np.log(np.clip(h_init, 1e-12, None))

        def negR(c):
            logh = logh0 + c @ B
            h = np.exp(np.clip(logh, -30.0, 30.0))
            return -R_of_fft(h)

        best_c = np.zeros(K)
        best_val = -R_of_fft(h_init)
        rng = np.random.default_rng(12345)
        # multistart Nelder-Mead
        starts = [np.zeros(K)]
        for _ in range(n_try - 1):
            starts.append(rng.normal(0, 0.05, K))
        for c0 in starts:
            if not time_left():
                break
            try:
                res = minimize(negR, c0, method='Nelder-Mead',
                               options={'maxiter': maxiter,
                                        'xatol': 1e-4, 'fatol': 1e-9})
                if res.fun < best_val:
                    best_val = res.fun
                    best_c = res.x
            except Exception:
                pass
        logh = logh0 + best_c @ B
        h = np.exp(np.clip(logh, -30.0, 30.0))
        r = R_of_fft(h)
        if r > bestR:
            bestR = r
            best = h.copy()
        return r

    # Work at moderate N first, then higher.
    # First, try to improve quality at a working resolution.
    work_N = min(best.size, 20000)
    hw = downsample(best, work_N) if best.size != work_N else best.copy()
    if time_left():
        polish_basis(hw, nbump=10, scales=(0.03, 0.06, 0.12, 0.25, 0.5),
                     maxiter=500, n_try=3)

    # Scale up: interpolate best to higher N and polish there.
    for N in (40000, 80000, 120000, 200000):
        if not time_left():
            break
        hn = upsample(best, N)
        if time_left():
            polish_basis(hn, nbump=12, scales=(0.02, 0.05, 0.1, 0.2, 0.4),
                         maxiter=400, n_try=2)

    # Final L-BFGS polish on log-heights at moderate N (fast enough).
    def lbfgs_polish(h_init, maxiter=800):
        nonlocal best, bestR
        N = h_init.size
        x0 = np.log(np.clip(h_init, 1e-12, None))

        def negR(x):
            return -R_of_fft(np.exp(np.clip(x, -30.0, 30.0)))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 8})
            cand = np.exp(np.clip(res.x, -30.0, 30.0))
        except Exception:
            return
        r = R_of_fft(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    if time_left():
        lbfgs_polish(downsample(best, 20000), maxiter=1000)
    if time_left():
        lbfgs_polish(downsample(best, 40000), maxiter=600)

    return best

