import time
from scipy.optimize import minimize


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def _resample(h, N):
    x_old = (np.arange(h.size) + 0.5) / h.size
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _smooth_obj(x, beta):
    h = np.exp(x)
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return 1e10
    L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    bL = beta * Lf
    mx = bL.max()
    m_beta = (mx + np.log(np.exp(bL - mx).sum())) / beta
    if m_beta <= 0 or not np.isfinite(m_beta):
        return 1e10
    q = (Lf[:-1] * Lf[:-1] + Lf[:-1] * Lf[1:] + Lf[1:] * Lf[1:]).sum() / 3.0
    denom = (s * s) * m_beta
    if denom <= 0:
        return 1e10
    return -q / denom


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 50
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    def consider(cand):
        nonlocal best, bestR
        cand = np.clip(np.asarray(cand, dtype=float), 0.0, None)
        if cand.sum() <= 0 or cand.size > 200000:
            return False
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()
            return True
        return False

    def refine(h_init, maxiter=3000):
        h_init = np.clip(np.asarray(h_init, dtype=float), 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x0 = np.log(h_init + 1e-12)

        def negR(x):
            return -R_of(np.exp(x))

        try:
            res = minimize(negR, x0, method='L-BFGS-B',
                           bounds=[(-20.0, 10.0)] * N,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10})
            consider(np.exp(res.x))
        except Exception:
            return

    def homotopy(h_init, betas=(50, 200, 1000, 5000)):
        h_init = np.clip(np.asarray(h_init, dtype=float), 0.0, None)
        if h_init.sum() <= 0:
            return
        N = h_init.size
        x = np.log(h_init + 1e-12)
        for beta in betas:
            if not time_left():
                break
            try:
                res = minimize(_smooth_obj, x, args=(beta,), method='L-BFGS-B',
                               bounds=[(-20.0, 10.0)] * N,
                               options={'maxiter': 3000, 'maxfun': 30000})
                x = res.x
            except Exception:
                break
            consider(np.exp(x))

    # Start improvement: work at the start's resolution and a couple of refinements.
    N0 = best.size
    if time_left():
        homotopy(best)
    if time_left():
        refine(best)
    for N in [max(N0, 100), 200]:
        if not time_left():
            break
        N = min(N, 200000)
        refine(_resample(best, N))

    # Multi-resolution upsample ladder: go higher than before to exploit the
    # extra resolution, which tends to improve R for this problem.
    ladder = [400, 800, 1500, 3000, 6000]
    for N in ladder:
        if not time_left():
            break
        base = _resample(best, N)
        if time_left():
            homotopy(base)
        if time_left():
            refine(base)

    # Main loop: alternate homotopy and direct refine.
    rng = np.random.default_rng(20240607)
    Ns = [200, 400, 800, 1500, 3000]
    idx = 0
    while time_left():
        N = Ns[idx % len(Ns)]
        idx += 1
        N = min(N, 200000)
        base = _resample(best, N)
        if time_left() and rng.random() < 0.5:
            homotopy(base)
        else:
            refine(base)

    # Final polish at current resolution.
    t_guard = t0 + budget_seconds * 0.96
    while time.process_time() < t_guard:
        refine(best, maxiter=2000)

    return best

