    return q / denom


def R_of_fft(h):
    """Exact R using FFT convolution (faster for large N)."""
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    N = h.size
    nfft = 1
    while nfft < 2 * N:
        nfft *= 2
    H = np.fft.rfft(h, nfft)
    c = np.fft.irfft(H * H, nfft)[:2 * N - 1]
    L = np.empty(2 * N + 1)
    L[0] = 0.0
    L[1:2 * N] = c
    L[2 * N] = 0.0
    m = L.max()
    if m <= 0:
        return -1.0
    q = (L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]).sum() / 3.0
    denom = (s * s) * m
    if denom <= 0:
        return -1.0
    return q / denom


def recurrence_exact(N):
    """h_n = C(2n,n)/4^n, the M=1 recurrence, computed directly."""
    h = np.empty(N)
    h[0] = 1.0
    for n in range(1, N):
        h[n] = h[n - 1] * (2 * n - 1) / (2 * n)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def time_left():
        return time.process_time() < deadline

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        n = 50
        x = (np.arange(n) + 0.5) / n
        h0 = np.clip(np.cos(np.pi * (x - 0.5)) ** 2, 0.0, None)

    best = h0.copy()
    bestR = R_of(best)

    # --- Build exact M=1 recurrence at high N (the Abel kernel) ---
    N_rec = 200000
    h_rec = None
    if time_left():
        h_rec = recurrence_exact(N_rec)
        r = R_of_fft(h_rec)
        if r > bestR:
            bestR = r
            best = h_rec.copy()

    # --- Experiment: logarithmic multiplicative correction ---
    # u_i = log((i+1)/N) - log(0.5); h2 = h * exp(a*u + b*u^2)
    if h_rec is not None and time_left():
        N = h_rec.size
        i = np.arange(N) + 1.0
        u = np.log(i / N) - np.log(0.5)
        u2 = u * u

        def make_exp(a, b):
            return h_rec * np.exp(a * u + b * u2)

        def make_lin(a, b):
            return np.clip(h_rec * (1.0 + a * u + b * u2), 0.0, None)

        # Coarse grid scan (exp variant)
        best_a, best_b = 0.0, 0.0
        best_r_exp = bestR
        grid = [-0.5, -0.25, -0.1, 0.0, 0.1, 0.25, 0.5]
        for a in grid:
            if not time_left():
                break
            for b in grid:
                if not time_left():
                    break
                if a == 0.0 and b == 0.0:
                    continue
                h2 = make_exp(a, b)
                r = R_of_fft(h2)
                if r > best_r_exp:
                    best_r_exp = r
                    best_a, best_b = a, b
                    if r > bestR:
                        bestR = r
                        best = h2.copy()

        # Coarse grid scan (linear variant)
        best_r_lin = bestR
        la, lb = 0.0, 0.0
        for a in grid:
            if not time_left():
                break
            for b in grid:
                if not time_left():
                    break
                if a == 0.0 and b == 0.0:
                    continue
                h2 = make_lin(a, b)
                r = R_of_fft(h2)
                if r > best_r_lin:
                    best_r_lin = r
                    la, lb = a, b
                    if r > bestR:
                        bestR = r
                        best = h2.copy()

        # Nelder-Mead refine on exp variant
        if time_left():
            def neg_exp(x):
                a = max(-5.0, min(5.0, x[0]))
                b = max(-5.0, min(5.0, x[1]))
                return -R_of_fft(make_exp(a, b))

            try:
                res = minimize(neg_exp, np.array([best_a, best_b]),
                               method='Nelder-Mead',
                               options={'maxiter': 300, 'xatol': 1e-5,
                                        'fatol': 1e-9})
                a_r = max(-5.0, min(5.0, res.x[0]))
                b_r = max(-5.0, min(5.0, res.x[1]))
                h2 = make_exp(a_r, b_r)
                r = R_of_fft(h2)
                if r > bestR:
                    bestR = r
                    best = h2.copy()
                    best_a, best_b = a_r, b_r
            except Exception:
                pass

        # Nelder-Mead refine on linear variant
        if time_left():
            def neg_lin(x):
                a = max(-5.0, min(5.0, x[0]))
                b = max(-5.0, min(5.0, x[1]))
                return -R_of_fft(make_lin(a, b))

            try:
                res = minimize(neg_lin, np.array([la, lb]),
                               method='Nelder-Mead',
                               options={'maxiter': 300, 'xatol': 1e-5,
                                        'fatol': 1e-9})
                a_r = max(-5.0, min(5.0, res.x[0]))
                b_r = max(-5.0, min(5.0, res.x[1]))
                h2 = make_lin(a_r, b_r)
                r = R_of_fft(h2)
                if r > bestR:
                    bestR = r
                    best = h2.copy()
            except Exception:
                pass

    return best
